"""VWAP armed-candidate direction context repair. Observation only; no order or strategy mutations."""
import argparse, fcntl, hashlib, json, os, shutil, subprocess, sys, tempfile
from datetime import datetime, timezone
from pathlib import Path
FILES=json.loads(bytes.fromhex(''))
ORIGINALS=json.loads(bytes.fromhex(''))
HASHES=json.loads(bytes.fromhex(''))

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None

def validate(root):
    for relative,content in FILES.items():
        if hashlib.sha256(content.encode()).hexdigest()!=HASHES[relative]:
            raise SystemExit('PAYLOAD_HASH_MISMATCH:'+relative)
        if digest(root/relative) not in {ORIGINALS[relative],HASHES[relative]}:
            raise SystemExit('SOURCE_CHANGED_NO_FILES_WRITTEN:'+relative)
        if relative.endswith('.py'):compile(content,relative,'exec')

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    group=parser.add_mutually_exclusive_group()
    group.add_argument('--check',action='store_true')
    group.add_argument('--test',action='store_true')
    args=parser.parse_args();root=Path.cwd()
    if not (root/'backend/market_lab').is_dir():parser.error('Run from ~/RB-ITOS-AI')
    validate(root)
    print(json.dumps(dict(status='VALIDATED',files=list(FILES),observation_only=True,tests_run=False)),flush=True)
    if args.check:return
    if args.test:
        with tempfile.TemporaryDirectory(prefix='hilega-vwap-candidate-tests-') as folder:
            stage=Path(folder);tests=stage/'tests';tests.mkdir()
            for relative,content in FILES.items():
                target=stage/'files'/relative;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
                if relative.startswith('tests/'):(tests/Path(relative).name).write_text(content)
            (tests/'conftest.py').write_text(
                'import sys\n'+
                'sys.path.insert(0, '+repr(str(root/'backend'))+')\n'+
                'sys.path.insert(0, '+repr(str(stage/'files'))+')\n'+
                'import market_lab\n'+
                'market_lab.__path__.insert(0, '+repr(str(stage/'files/backend/market_lab'))+')\n')
            result=subprocess.run([sys.executable,'-m','pytest','-q',str(tests)],cwd=root)
            raise SystemExit(result.returncode)
    # Use the independent collector's own lock; never stop or restart trading workers.
    lock=root/'data/live-observation/hilega-vwap-signal-v1/collector.lock'
    lock.parent.mkdir(parents=True,exist_ok=True)
    with lock.open('a') as stream:
        try:fcntl.flock(stream,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise SystemExit('STOP_VWAP_COLLECTOR_BEFORE_INSTALL; no files written') from None
        validate(root)
        backup=root/'backups'/('vwap-candidates-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
        backup.mkdir(parents=True);installed=[];created=[]
        try:
            for relative,content in FILES.items():
                target=root/relative
                if digest(target)==HASHES[relative]:continue
                if target.exists():
                    old=backup/relative;old.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,old)
                else:created.append(relative)
                target.parent.mkdir(parents=True,exist_ok=True)
                temporary=target.with_name(target.name+'.vwap-candidate.tmp')
                with temporary.open('w',encoding='utf-8') as handle:
                    handle.write(content);handle.flush();os.fsync(handle.fileno())
                os.replace(temporary,target);installed.append(relative)
        except BaseException:
            for relative in reversed(installed):
                if (backup/relative).exists():shutil.copy2(backup/relative,root/relative)
                elif relative in created:(root/relative).unlink(missing_ok=True)
            raise
        (backup/'created-files.json').write_text(json.dumps(created,indent=2))
    print(json.dumps(dict(status='APPLIED',backup=str(backup),observation_only=True,
                         services_started=False,orders_sent=False,tests_run=False)))

if __name__=='__main__':main()
